#!/usr/bin/env bash
# Regenerates the docs that are produced from the code.
#
#   docs/DETECTORS.md   `scrub detectors --markdown`, the rule catalog of redactor-core
#
# (docs/ACCURACY.md is generated by the corpus gates, `cargo test -p redactor-core --test corpus`.)
#
# Usage: tools/gen-docs.sh
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"

cargo build -q -p scrub
tmp="$(mktemp)"
trap 'rm -f "$tmp"' EXIT
"$ROOT/target/debug/scrub" detectors --markdown > "$tmp"
if [ ! -s "$tmp" ]; then
  echo "scrub detectors --markdown printed nothing" >&2
  exit 1
fi
mv "$tmp" docs/DETECTORS.md
chmod 644 docs/DETECTORS.md
echo "wrote docs/DETECTORS.md ($(grep -c '^| `' docs/DETECTORS.md) rules)"
